#include <bits/stdc++.h>
#define MAXN 200100
#define LL long long
using namespace std;

typedef pair<LL,LL> pll;
LL n,m;
LL x[MAXN],p[MAXN];
vector<pll> diff;
pll key;

pll getIntersection(pll p1,pll p2)
{
	LL tx=max(p1.first+p1.second,p2.first+p2.second);
	LL ty=max(p1.second-p1.first,p2.second-p2.first);
	return {(tx-ty)/2,(tx+ty)/2};
}

void work()
{
	diff.clear();
	key={0,-0x3f3f3f3f3f3f3f3f};
	cin>>n>>m;
	m*=2;
	for (int i=1;i<=n;i++)
	{
		cin>>x[i]>>p[i];
		x[i]*=2;
		p[i]*=2;
		diff.push_back({x[i]-p[i],1});
		diff.push_back({x[i],-2});
		diff.push_back({x[i]+p[i],1});
	}
	sort(diff.begin(), diff.end());
	LL a=0,d=0;
	LL lst=0;
	for (auto p:diff)
	{
		if (p.first!=lst)
		{
			a=a+(p.first-lst)*d;
			lst=p.first;
			if (a>m)
				key=getIntersection(key,{p.first,a-m});
		}
		d+=p.second;
	}
	for (int i=1;i<=n;i++)
		if (getIntersection(key,{x[i],p[i]})==pll(x[i],p[i]))
			cout<<'1';
		else
			cout<<'0';
	cout<<endl;
}

int main()
{
	int casenum=1;
	cin>>casenum;
	for (int testcase=1;testcase<=casenum;testcase++)
		work();
	return 0;
}

#include <bits/stdc++.h>
#define MAXN 200100
#define LL long long
#define MOD 998244353
using namespace std;

LL dp[MAXN][8][8];
string s;
int main()
{
	cin>>s;
	dp[0][0][0]=1;
	for (int i=0;i<s.size();i++)
		for (int mask1=0;mask1<8;mask1++)
			for (int mask2=0;mask2<8;mask2++)
			{
				dp[i][mask1][mask2]%=MOD;
				for (int m=0;m<8;m++)
				{
					bool flag=false;
					for (int j=0;j<3;j++)
						if (s[i]=='0' && (mask2>>j)%2==0 && (m>>j)%2==1)
						{
							flag=true;
							break;
						}
					if (flag)
						continue;
					int tmpmask1=mask1;
					int tmpmask2=mask2;
					for (int j=0;j<3;j++)
						if (s[i]-'0'!=((m>>j)&1))
							tmpmask2|=(1<<j);
					for (int j=0;j<3;j++)
						if (m==(1<<j) || m==7-(1<<j))
							tmpmask1|=(1<<j);
					dp[i+1][tmpmask1][tmpmask2]+=dp[i][mask1][mask2];
				}
			}
	LL ans=0;
	for (int i=0;i<8;i++)
		ans+=dp[s.size()][7][i];
	cout<<ans%MOD<<endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define MAXN 5100
typedef pair<int,int> pii;
int n;
