int lv[MAXN],rv[MAXN];
vector<pii> ans;


void work()
{
	ans.clear();
	cin>>n;
	for (int i=1;i<=n;i++)
	{
		lv[i]=rv[i]=i;
		cin>>(good[i]+i);
	}
	for (int len=2;len<=n;len++)
		for (int l=1;l<=n+1-len;l++)
		{
			int r=l+len-1;
			if (good[l][r]=='1' && lv[l]!=lv[r] && rv[l]!=rv[r])
			{
				ans.push_back({l,r});
				vector<int> tmp[2];
				int id=1;
				tmp[0].push_back({l});
				tmp[1].push_back({r});
				for (int i=rv[l]+1;i<lv[r];i++)
					if (lv[i]==i)
					{
						ans.push_back({tmp[id].back(),i});
						tmp[id].push_back(i);
						id^=1;
					}
				int lm=lv[l];
				int rm=rv[r];
				for (int i=lm;i<=rm;i++)
				{
					lv[i]=lm;
					rv[i]=rm;
				}
			}
		}
	for (auto p:ans)
